"""Timing-only copy of the frozen reference; generated by wrapping calls.

All original statements and floating operations remain in their original order.
The original reference is used for uninstrumented wall times and exact parity.
"""
import numpy as np
import shapely as sh
from data3001.preprocessing.prep_core import cells
from data3001.modelling.baselines.actual_origin_displacement_s3_e5_inputs import ActualOriginKernel
from data3001.modelling.baselines.spatial_borrowing_s3_e1_inputs import neighbours,FALLBACK
from data3001.modelling.common.qualified_count_inputs import EXIT
class ProfiledReference(ActualOriginKernel):

    def query_safe(self, query):
        g = self.geometry
        if not self.timer.call('query_safe:np.isfinite', np.isfinite, [query.lon, query.lat]).all() or not -180 <= query.lon < 180 or (not -90 <= query.lat < 90) or (int(self.timer.call('query_safe:cells', cells, self.timer.call('query_safe:np.array', np.array, [query.lon]), self.timer.call('query_safe:np.array', np.array, [query.lat]))[0]) != query.origin) or (query.origin not in g.states) or (not self.timer.call('query_safe:sh.intersects_xy:g.region', sh.intersects_xy, g.region, query.lon, query.lat)) or (not self.timer.call('query_safe:sh.intersects_xy:g.domain', sh.intersects_xy, g.domain, query.lon, query.lat)):
            raise ValueError('Invalid actual prediction-time coordinate')
        return not (self.timer.call('query_safe:sh.intersects_xy:g.high', sh.intersects_xy, g.high, query.lon, query.lat) or self.timer.call('query_safe:sh.intersects_xy:g.intermediate', sh.intersects_xy, g.intermediate, query.lon, query.lat))

    def certificates(self, query, donors):
        """A fully valid path inside a water/state rectangle needs no hourly checks."""
        g = self.geometry
        sx, sy = (donors.lon.to_numpy(), donors.lat.to_numpy())
        xmin, xmax = (query.lon + (donors.x_min.to_numpy() - sx), query.lon + (donors.x_max.to_numpy() - sx))
        ymin, ymax = (query.lat + (donors.y_min.to_numpy() - sy), query.lat + (donors.y_max.to_numpy() - sy))
        possible = donors.full_interval.to_numpy(bool) & (xmin >= -180) & (xmax < 180) & (ymin >= -90) & (ymax < 90)
        xmin = (xmin + 180) % 360 - 180
        xmax = (xmax + 180) % 360 - 180
        xmin -= 1e-10
        xmax += 1e-10
        ymin -= 1e-10
        ymax += 1e-10
        possible &= (xmin >= -180) & (xmax < 180) & (xmin <= xmax) & (ymin >= -90) & (ymax < 90)
        ix = self.timer.call('certificates:np.flatnonzero', np.flatnonzero, possible)
        good = self.timer.call('certificates:np.zeros', np.zeros, len(donors), dtype=bool)
        if not len(ix):
            return good
        boxes = self.timer.call('certificates:sh.box:xmin[ix]', sh.box, xmin[ix], ymin[ix], xmax[ix], ymax[ix])
        water = self.timer.call('certificates:sh.covers:g.domain', sh.covers, g.domain, boxes) & ~self.timer.call('certificates:sh.intersects:g.high', sh.intersects, g.high, boxes) & ~self.timer.call('certificates:sh.intersects:g.intermediate', sh.intersects, g.intermediate, boxes)
        x0 = self.timer.call('certificates:np.floor', np.floor, xmin[ix] + 180).astype(int)
        x1 = self.timer.call('certificates:np.floor', np.floor, xmax[ix] + 180).astype(int) + 1
        y0 = self.timer.call('certificates:np.floor', np.floor, ymin[ix] + 90).astype(int)
        y1 = self.timer.call('certificates:np.floor', np.floor, ymax[ix] + 90).astype(int) + 1
        p = self.state_prefix
        number = p[y1, x1] - p[y0, x1] - p[y1, x0] + p[y0, x0]
        good[ix] = water & (number == (x1 - x0) * (y1 - y0))
        return good

    def classify(self, query, donors, fitting_ids, *, certificates=True, check=lambda: None):
        """Predict using one query start and only fitting donor paths; no query truth."""
        fitting_ids = set(map(int, fitting_ids))
        if query.id in fitting_ids or not set(map(int, donors.id)).issubset(fitting_ids):
            raise PermissionError('Whole-ID leakage in displacement donor role')
        if not donors.horizon_days.eq(query.horizon).all() or not donors.origin_cell_1.isin(neighbours(query.origin)).all():
            raise ValueError('Wrong horizon or non-neighbour donor')
        if len(donors) and (not (self.timer.call('classify:sh.intersects_xy:self.geometry.region', sh.intersects_xy, self.geometry.region, donors.lon, donors.lat).all() and self.timer.call('classify:sh.intersects_xy:self.geometry.domain', sh.intersects_xy, self.geometry.domain, donors.lon, donors.lat).all())):
            raise ValueError('Original donor outside permitted R/D')
        n = len(donors)
        out = self.timer.call('classify:np.full', np.full, n, FALLBACK, dtype=np.int64)
        why = self.timer.call('classify:np.zeros', np.zeros, n, dtype=np.int16)
        profile = dict(donors=n, certified=0, literal_pairs=0, hourly_steps=0)
        if not self.query_safe(query):
            why[:] = 11
            return (out, why, profile)
        if not n:
            return (out, why, profile)
        g, t = (self.geometry, self.tracks)
        for first in range(0, n, 2048):
            check()
            last = min(first + 2048, n)
            part = donors.iloc[first:last]
            cert = self.certificates(query, part) if certificates else self.timer.call('classify:np.zeros', np.zeros, len(part), dtype=bool)
            ci = self.timer.call('classify:np.flatnonzero', np.flatnonzero, cert)
            sx = part.lon.to_numpy()
            sy = part.lat.to_numpy()
            if len(ci):
                ex = (query.lon + (part.end_lon.to_numpy()[ci] - sx[ci]) + 180) % 360 - 180
                ey = query.lat + (part.end_lat.to_numpy()[ci] - sy[ci])
                out[first + ci] = self.timer.call('classify:cells', cells, ex, ey)
            profile['certified'] += int(cert.sum())
            active = self.timer.call('classify:np.flatnonzero', np.flatnonzero, ~cert)
            profile['literal_pairs'] += len(active)
            starts = part.start.to_numpy(int)
            ends = part.track_end.to_numpy(int)
            epochs = part.epoch.to_numpy(float)
            prevx = self.timer.call('classify:np.full', np.full, len(part), query.lon)
            prevy = self.timer.call('classify:np.full', np.full, len(part), query.lat)
            for step in range(1, 24 * query.horizon + 1):
                if not len(active):
                    break
                if step % 16 == 0:
                    check()
                profile['hourly_steps'] += len(active)
                loc = starts[active] + step
                present = loc < ends[active]
                why[first + active[~present]] = 7
                active = active[present]
                loc = loc[present]
                if not len(active):
                    break
                timed = t.time[loc] == epochs[active] + 3600 * step
                why[first + active[~timed]] = 5
                active = active[timed]
                loc = loc[timed]
                if not len(active):
                    break
                x = (query.lon + (t.lon[loc] - sx[active]) + 180) % 360 - 180
                y = query.lat + (t.lat[loc] - sy[active])
                valid = t.valid[loc] & self.timer.call('classify:np.isfinite', np.isfinite, x) & self.timer.call('classify:np.isfinite', np.isfinite, y) & (y >= -90) & (y < 90)
                why[first + active[~valid]] = 1
                active = active[valid]
                x = x[valid]
                y = y[valid]
                if not len(active):
                    break
                inside = self.timer.call('classify:sh.intersects_xy:g.domain', sh.intersects_xy, g.domain, x, y)
                high = inside & self.timer.call('classify:sh.intersects_xy:g.high', sh.intersects_xy, g.high, x, y)
                mid = inside & self.timer.call('classify:sh.intersects_xy:g.intermediate', sh.intersects_xy, g.intermediate, x, y)
                code = self.timer.call('classify:cells', cells, x, y)
                reason = self.timer.call('classify:np.zeros', np.zeros, len(active), dtype=np.int16)
                reason[inside & ~self.timer.call('classify:np.isin', np.isin, code, list(g.states))] = 4
                reason[high & mid] = 2
                reason[high ^ mid] = 3
                xy = self.timer.call('classify:np.stack', np.stack, (self.timer.call('classify:np.column_stack', np.column_stack, (prevx[active], prevy[active])), self.timer.call('classify:np.column_stack', np.column_stack, (x, y))), axis=1)
                lines = self.timer.call('classify:sh.linestrings:xy', sh.linestrings, xy)
                high = self.timer.call('classify:sh.intersects:g.high_D', sh.intersects, g.high_D, lines)
                mid = self.timer.call('classify:sh.intersects:g.intermediate_D', sh.intersects, g.intermediate_D, lines)
                reason[high & mid] = 6
                reason[high ^ mid] = 10
                failed = reason > 0
                why[first + active[failed]] = reason[failed]
                exited = ~failed & ~inside
                out[first + active[exited]] = EXIT
                remain = ~failed & inside
                if step == 24 * query.horizon:
                    out[first + active[remain]] = code[remain]
                    active = self.timer.call('classify:np.array', np.array, [], dtype=int)
                else:
                    prevx[active[remain]] = x[remain]
                    prevy[active[remain]] = y[remain]
                    active = active[remain]
        if not self.timer.call('classify:np.array_equal', np.array_equal, out == FALLBACK, why > 0):
            raise AssertionError('Transfer outcome/reason mismatch')
        return (out, why, profile)
